pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzing the amount to send to go; the adversarial target will accept the call
    // but leave some leftover balance in C (by not forwarding back), so the reference
    // will drain it to owner while the mutant will not.
    function testFuzz_property(uint256 amount) public {
        // keep amount in a reasonable range so vm.deal works and avoids overflow edge cases
        amount = bound(amount, 1, 1 ether);

        // deploy a helper target that accepts the call but does not forward balance back
        ReceiverKeepBalance target = new ReceiverKeepBalance();

        // fund msg.sender (actor) so it can call go with value
        address actor = address(0xABCD);
        vm.deal(actor, amount);

        // we need to make the contract's hard-coded target address point to our helper.
        // The original contract uses a fixed address; to route through our helper we will
        // have the actor perform a low-level call to the contract's go while making the
        // helper the recipient of the forwarded funds by causing the contract's call to
        // that fixed address to succeed but we cannot change the hardcoded address.
        // Instead, we exploit that the C contract forwards msg.value to the hardcoded
        // target address; therefore we must deploy a contract at that exact address.
        // Forge allows creating a contract at an arbitrary address by using create2 with
        // a salt chosen so the address matches. We'll deploy a thin proxy at the hardcoded
        // target address which forwards to our ReceiverKeepBalance.

        // compute desired address (from reference source):
        address fixedTarget = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // Deploy a Forwarder at that fixed address via CREATE2 using a factory
        Deployer deployer = new Deployer();
        deployer.deployAt(fixedTarget, address(target));

        // Now call c.go with actor sending amount
        vm.prank(actor);
        // send value to c.go
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
        // call should succeed (reference and mutant both succeed because target accepts)
        require(ok);

        // The general property we assert: after go completes, reference contract balance is zero.
        // This holds for the correct C for all inputs; the mutant that removed the final transfer
        // will leave a non-zero balance for some inputs (the fuzzer will find one).
        assertTrue(address(c).balance == 0);
    }
