// minimal helper that will accept the forwarded funds and keep them (not forwarding back)
contract ReceiverKeepBalance {
    fallback() external payable {
        // accept funds and do nothing -> leaves balance in this contract
    }
}

// small deployer that can place a forwarder at an exact address via CREATE2
contract Deployer {
    // deploy a tiny forwarder contract that forwards calls/receives to a target
    function deployAt(address dest, address target) public {
        bytes memory init = getInitCode(target);
        bytes32 salt = bytes32(uint256(uint160(dest)));
        address deployed;
        assembly {
            deployed := create2(0, add(init, 0x20), mload(init), salt)
            if iszero(deployed) { revert(0, 0) }
        }
        // verify address matches
        require(deployed == dest, "deploy failed to place at dest");
    }

    // init code for a minimal contract that forwards any call/value to `target`.
    function getInitCode(address target) internal pure returns (bytes memory) {
        // runtime code:
        // 60_?? push1 <size> 60_?? push1 <offset> 39 CODECOPY 60_00 push1 00 RETURN
        // But simpler: we create a contract that stores target in its code and on fallback does nothing
        // We'll produce a contract that simply has a payable fallback that does nothing.
        // For placement we don't actually need forwarding behavior; the C contract does a call to the fixed address
        // and value is transferred; having a contract at that address which accepts value is sufficient.

        bytes memory runtime = hex"600a600c600039600a6000f3"; // simple runtime blob that returns empty
        // constructor: push runtime to memory and return it
        bytes memory init = abi.encodePacked(
            hex"61",
            uint16(runtime.length),
            hex"600b598138038101600a81526020013060205260206000f3",
            runtime
        );
        // The above is a generic constructor; for simplicity, return a simple payable fallback runtime that does nothing
        // Instead of crafting complex bytecode, use a simpler technique: deploy a contract with known bytecode that is payable and does nothing.
        // Here we fallback to deploying via runtime that is just "0x6000f3" which returns nothing; but make it payable by not reverting on receive.
        // To keep this minimal and deterministic, return a basic init that results in an empty-runtime contract which still can receive value.

        // Simpler approach: use standard minimal proxy pattern is complex; due to constraints, we will craft an init that returns a runtime which contains just "0x00" which is valid.
        // For reliability, return a simple byte array that will compile to something deployable.

        // However to keep code size manageable in this context, return a basic runtime that has a payable fallback (just stops).
        // EVM bytecode for: "stop" (0x00) is valid runtime. Constructor returns that.
        bytes memory simpleRuntime = hex"00"; // runtime: STOP
        bytes memory simpleInit = abi.encodePacked(hex"60", uint8(simpleRuntime.length), hex"60", uint8(0x0c), hex"39f3", simpleRuntime);
        return simpleInit;
    }
}

