            ok = true;
        } catch {
            ok = false;
        }
        // The general property: for any caller and any msg.value, the reference contract forwards the exact msg.value
        // to the external target so the contract's balance does not increase (address(c).balance == before).
        // We assert that observed behavior matches this general rule (this will hold on reference, and the mutant
        // which forwards 0 will make address(c).balance > before for some positive amount, causing this assertion
        // to fail for those inputs).
        assertTrue(address(c).balance == before);
    }
}
